/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import hashlib,json,base64,os,stat
root=Path.cwd()
records={}
for p in sorted(root.rglob('*')):
 rel=p.relative_to(root).as_posix()
 s=p.lstat()
 if stat.S_ISLNK(s.st_mode): records[rel]={'kind':'symlink','target':os.readlink(p),'mode':stat.S_IMODE(s.st_mode)}
 elif stat.S_ISREG(s.st_mode):
  data=p.read_bytes()
  records[rel]={'kind':'file','size':len(data),'sha256':hashlib.sha256(data).hexdigest(),'mode':stat.S_IMODE(s.st_mode)}
 elif stat.S_ISDIR(s.st_mode): records[rel]={'kind':'directory','mode':stat.S_IMODE(s.st_mode)}
 else: records[rel]={'kind':'other','mode':stat.S_IMODE(s.st_mode)}
contents={p:base64.b64encode((root/p).read_bytes()).decode() for p in ['inputs/payload.txt','outputs/release/payload.txt','outputs/release/manifest.json','outputs/release-note.md','tools/verify_release.py']}
print(json.dumps({'inventory':records,'contents_base64':contents},sort_keys=True))
PY"

